from copy import deepcopy
from datetime import datetime
from typing import Any

from lfx.base.tools.run_flow import RunFlowBaseComponent
from lfx.log.logger import logger
from lfx.schema.data import Data
from lfx.schema.dotdict import dotdict


class RunFlowComponent(RunFlowBaseComponent):
    display_name = "Run Flow"
    description = (
        "Executes another flow from within the same project. Can also be used as a tool for agents."
        " \n **Select a Flow to use the tool mode**"
    )
    documentation: str = "https://docs.langflow.org/run-flow"
    beta = True
    name = "RunFlow"
    icon = "Workflow"

    # Keep the concrete class templates detached from the base-class templates;
    # Component.__init__ still makes the per-instance copies used at runtime.
    inputs = deepcopy(RunFlowBaseComponent.get_base_inputs())
    outputs = deepcopy(RunFlowBaseComponent.get_base_outputs())

    async def update_build_config(
        self,
        build_config: dotdict,
        field_value: Any,
        field_name: str | None = None,
    ):
        missing_keys = [key for key in self.default_keys if key not in build_config]
        for key in missing_keys:  # TODO: create a defaults dict to avoid hardcoding the defaults here
            if key == "flow_name_selected":
                build_config[key] = {"options": [], "options_metadata": [], "value": None}
            elif key == "flow_id_selected":
                build_config[key] = {"value": None}
            elif key == "cache_flow":
                build_config[key] = {"value": False}
            else:
                build_config[key] = {}
        if field_name == "flow_name_selected" and (build_config.get("is_refresh", False) or field_value is None):
            # refresh button was clicked or componented was initialized, so list the flows
            options: list[str] = await self.alist_flows_by_flow_folder()
            build_config["flow_name_selected"]["options"] = [flow.data["name"] for flow in options]
            build_config["flow_name_selected"]["options_metadata"] = []
            for flow in options:
                # populate options_metadata
                build_config["flow_name_selected"]["options_metadata"].append(
                    {"id": flow.data["id"], "updated_at": flow.data["updated_at"]}
                )
                # update selected flow if it is stale
                if str(flow.data["id"]) == self.flow_id_selected:
                    await self.check_and_update_stale_flow(flow, build_config)
        elif field_name in {"flow_name_selected", "flow_id_selected"} and field_value is not None:
            # flow was selected by name or id, so get the flow and update the bcfg
            try:
                # derive flow id if the field_name is flow_name_selected
                build_config["flow_id_selected"]["value"] = (
                    self.get_selected_flow_meta(build_config, "id") or build_config["flow_id_selected"]["value"]
                )
                updated_at = self.get_selected_flow_meta(build_config, "updated_at")
                await self.load_graph_and_update_cfg(
                    build_config, build_config["flow_id_selected"]["value"], updated_at
                )
            except Exception as e:
                msg = f"Error building graph for flow {field_value}"
                await logger.aexception(msg)
                raise RuntimeError(msg) from e

        return build_config

    def get_selected_flow_meta(self, build_config: dotdict, field: str) -> dict:
        """Get the selected flow's metadata from the build config."""
        return build_config.get("flow_name_selected", {}).get("selected_metadata", {}).get(field)

    async def load_graph_and_update_cfg(
        self,
        build_config: dotdict,
        flow_id: str,
        updated_at: str | datetime,
    ) -> None:
        """Load a flow's graph and update the build config."""
        graph = await self.get_graph(
            flow_id_selected=flow_id,
            updated_at=self.get_str_isots(updated_at),
        )
        self.update_build_config_from_graph(build_config, graph)

    def should_update_stale_flow(self, flow: Data, build_config: dotdict) -> bool:
        """Check if the flow should be updated."""
        return (
            (updated_at := self.get_str_isots(flow.data["updated_at"]))  # true updated_at date just fetched from db
            and (stale_at := self.get_selected_flow_meta(build_config, "updated_at"))  # outdated date in bcfg
            and self._parse_timestamp(updated_at) > self._parse_timestamp(stale_at)  # stale flow condition
        )

    async def check_and_update_stale_flow(self, flow: Data, build_config: dotdict) -> None:
        """Check if the flow should be updated and update it if necessary."""
        # TODO: improve contract/return value
        if self.should_update_stale_flow(flow, build_config):
            await self.load_graph_and_update_cfg(
                build_config,
                flow.data["id"],
                flow.data["updated_at"],
            )

    def get_str_isots(self, date: datetime | str) -> str:
        """Get a string timestamp from a datetime or string."""
        return date.isoformat() if hasattr(date, "isoformat") else date

"""Deterministic LF-10 tool bridge to the canonical LF-70 flow."""

from __future__ import annotations

import json
import os
from typing import Any
from urllib import parse, request
from uuid import uuid4

from lfx.custom.custom_component.component import Component
from lfx.inputs.inputs import MessageTextInput
from lfx.schema.message import Message
from lfx.template.field.base import Output
from pydantic import ValidationError

from hulubul.core.models.operational import DataOperationResult, OperationalError
from hulubul.core.models.operational.enums import ErrorCode
from hulubul.core.models.operational.errors import ERROR_POLICY
from hulubul.core.models.operational.json_extraction import extract_json_object_text

__all__ = ["HulubulLf70FlowTool"]

DEFAULT_LF70_FLOW_ID = "a6ac335f-3b94-4906-9bdc-eb5c30cc010d"
DEFAULT_LANGFLOW_BASE_URL = "http://localhost:7860"
LANGFLOW_API_KEY_ENV = "LANGFLOW_API_KEY"


class HulubulLf70FlowTool(Component):
    """Expose canonical LF-70 as one validated Agent tool for LF-10.

    Langflow's stock RunFlow component currently exposes an empty toolset for
    the LF-70 flow in this project, so LF-10 cannot call data access at runtime.
    This component keeps the boundary deterministic: LF-10 supplies exactly one
    DataOperationRequest JSON string, this bridge runs LF-70's public API, and
    only validated DataOperationResult JSON is returned to LF-10.
    """

    display_name = "LF-70 Flow Tool"
    description = "Call the canonical LF-70 flow and return a validated DataOperationResult."
    icon = "workflow"
    name = "HulubulLf70FlowTool"

    inputs = [  # noqa: RUF012
        MessageTextInput(  # type: ignore[call-arg]
            name="input_value",
            display_name="DataOperationRequest JSON",
            info="Raw DataOperationRequest JSON string to send to LF-70.",
            required=True,
        ),
        MessageTextInput(  # type: ignore[call-arg]
            name="session_id",
            display_name="Session ID",
            info="Session ID for the LF-70 run.",
            required=False,
            advanced=True,
        ),
        MessageTextInput(  # type: ignore[call-arg]
            name="target_flow_id",
            display_name="LF-70 Flow ID",
            info="Canonical LF-70 flow ID to call.",
            value=DEFAULT_LF70_FLOW_ID,
            required=False,
            advanced=True,
        ),
        MessageTextInput(  # type: ignore[call-arg]
            name="base_url",
            display_name="Langflow Base URL",
            info="Langflow server URL.",
            value=DEFAULT_LANGFLOW_BASE_URL,
            required=False,
            advanced=True,
        ),
    ]

    outputs = [  # noqa: RUF012
        Output(  # type: ignore[call-arg]
            display_name="LF-70 Result",
            name="response",
            type_=Message,
            method="call_lf70",
        ),
    ]

    def call_lf70(self) -> Message:
        """Call LF-70 and return a validated DataOperationResult message."""
        input_text = self.input_value.text if isinstance(self.input_value, Message) else self.input_value
        if not isinstance(input_text, str) or not input_text.strip():
            return self._error_message(ErrorCode.INVALID_CONTRACT)

        flow_id = self.target_flow_id or DEFAULT_LF70_FLOW_ID
        base_url = self.base_url or DEFAULT_LANGFLOW_BASE_URL
        access_token = os.environ.get(LANGFLOW_API_KEY_ENV, "")
        session_id = str(uuid4())

        try:
            payload = self._build_run_payload(input_text, session_id)
            response = self._post_lf70(base_url, flow_id, access_token, payload)
        except Exception:
            return self._error_message(ErrorCode.MCP_OPERATION_FAILURE)

        return self._validated_result_message(response)

    @staticmethod
    def _build_run_payload(input_text: str, session_id: str) -> dict[str, str]:
        return {"input_value": input_text, "session_id": session_id}

    @staticmethod
    def _post_lf70(
        base_url: str, flow_id: str, access_token: str, payload: dict[str, str]
    ) -> dict[str, Any]:
        query = parse.urlencode(
            {
                "stream": "false",
                "output_type": "chat",
                "input_type": "chat",
            }
        )
        url = f"{base_url.rstrip('/')}/api/v1/run/{flow_id}?{query}"
        headers = {"Content-Type": "application/json"}
        if access_token:
            headers["x-api-key"] = access_token
        req = request.Request(
            url,
            data=json.dumps(payload).encode(),
            headers=headers,
            method="POST",
        )
        with request.urlopen(req, timeout=900) as response:  # noqa: S310 - local dev Langflow URL
            return json.loads(response.read().decode())

    def _validated_result_message(self, response: dict[str, Any]) -> Message:
        text = self._extract_message_text(response)
        if text is None:
            return self._error_message(ErrorCode.MALFORMED_AGENT_RESULT)
        try:
            parsed = json.loads(extract_json_object_text(text))
            result = DataOperationResult.model_validate_json(json.dumps(parsed, default=str))
        except (json.JSONDecodeError, TypeError, ValidationError):
            return self._error_message(ErrorCode.MALFORMED_AGENT_RESULT)
        return Message(text=result.model_dump_json())

    @staticmethod
    def _extract_message_text(response: dict[str, Any]) -> str | None:
        for run_output in response.get("outputs", []):
            for output in run_output.get("outputs", []):
                data = output.get("results", {}).get("message", {}).get("data")
                if isinstance(data, dict) and isinstance(data.get("text"), str):
                    return data["text"]
        return None

    @staticmethod
    def _error_message(code: ErrorCode) -> Message:
        policy = ERROR_POLICY[code]
        error = OperationalError(
            schema_version="1.0.0",
            correlation_id=uuid4(),
            code=policy.code,
            category=policy.category,
            message=policy.safe_message,
            retryable=policy.retryable,
        )
        return Message(text=error.model_dump_json())
